// Visão de Comando DEV: mesma inteligência, menor carga visual.
function commandForecastCandidates(){const now=Date.now(),out=[];(forecastSpi.regioes||[]).forEach(r=>{const rows=(r.previsao_horaria||[]).filter(x=>{const t=new Date(x.data_hora).getTime();return Number.isFinite(t)&&t>=now-10*60*1000&&t<=now+12*3600000});if(!rows.length)return;const worst=[...rows].sort((a,b)=>Number(b.rajada_kmh||0)-Number(a.rajada_kmh||0)||Number(b.probabilidade_chuva||0)-Number(a.probabilidade_chuva||0))[0];if(Number(worst.rajada_kmh||0)>=45||Number(worst.probabilidade_chuva||0)>=70||[95,96,99].includes(Number(worst.weather_code))){out.push({regiao:r.regiao,hora:worst.data_hora,rajada:worst.rajada_kmh,chuva:worst.precipitacao_mm,prob:worst.probabilidade_chuva,tempestade:[95,96,99].includes(Number(worst.weather_code))})}});return out.sort((a,b)=>Number(b.tempestade)-Number(a.tempestade)||Number(b.rajada)-Number(a.rajada)).slice(0,5)}
function commandBoardWindows(){return[{id:'agora',label:'AGORA',sub:'condição atual',from:-.5,to:.5},{id:'6h',label:'0–6H',sub:'prevenção imediata',from:0,to:6},{id:'12h',label:'6–12H',sub:'preparação regional',from:6,to:12},{id:'24h',label:'12–24H',sub:'planejamento',from:12,to:24},{id:'48h',label:'24–48H',sub:'antecipação',from:24,to:48}]}
function commandBackboneRoutesForRegion(name){const n=norm(name||'');const aliases=n==='LITORAL NORTE'?new Set(['CARAGUATATUBA','UBATUBA','SAO SEBASTIAO','ILHABELA']):new Set([n]);const ids=new Set();for(const f of (allFeatures||[])){const p=f.properties||{},cl=norm(p.cluster||''),ma=norm(p.municipio_a||''),mb=norm(p.municipio_b||'');if(cl===n||aliases.has(ma)||aliases.has(mb))ids.add(p.id_backbone||p.trecho||JSON.stringify([p.cabo,p.ponta_a,p.ponta_b]));}return ids.size}
function commandDddForRegion(name){const n=norm(name||'');if(n.includes('LITORAL SUL'))return'—';const m={'OSASCO':'11','JUNDIAI':'11','SAO JOSE DOS CAMPOS':'12','LITORAL NORTE':'12','BAURU':'14','SOROCABA':'15','RIBEIRAO PRETO':'16','SAO JOSE DO RIO PRETO':'17','PRESIDENTE PRUDENTE':'18','ARACATUBA':'18','CAMPINAS':'19'};return m[n]||'—'}
function commandDddLabel(ddd,lead,items=[]){return lead?.regiao||items[0]?.regiao||(String(ddd)==='11'?'Grande Jundiaí / Grande Osasco':'Sem referência')}
function commandRegionHasProblem(x){return Boolean(x&&(x.storm||Number(x.rain||0)>=0.1||Number(x.gust||0)>=40||Number(x.prob||0)>=50))}
function commandSitesForDdd(ddd){const d=String(ddd),arr=(siteEvents||[]).filter(x=>String(x.ddd??'')===d&&(d!=='11'||x.escopo_spi_ddd11===true));return{total:arr.length,ate4h:arr.filter(siteIsCritical).length}}
function commandSitesForRegions(ddd,names=[]){const ns=new Set((names||[]).map(norm)),ln=new Set(['CARAGUATATUBA','SAO SEBASTIAO','UBATUBA','ILHABELA']);const arr=(siteEvents||[]).filter(x=>{if(String(x.ddd??'')!==String(ddd))return false;if(String(ddd)==='11'&&x.escopo_spi_ddd11!==true)return false;const m=norm(x.municipio);return ns.has(m)||(ns.has('LITORAL NORTE')&&ln.has(m))});return{total:arr.length,ate4h:arr.filter(siteIsCritical).length}}
