function renderFireFocus(){const a=document.getElementById('fireFocusActive'),u=document.getElementById('fireFocusUrgent'),n=document.getElementById('fireFocusNearest');if(!a||!u||!n)return;a.textContent=fireEvents.length;const urg=fireEvents.filter(e=>norm(e.classificacao)==='URGENTE');u.textContent=urg.length;if(!fireEvents.length){n.innerHTML='<b>Nenhuma queimada ativa no Fire Core neste ciclo.</b>';return}const sorted=[...fireEvents].sort((x,y)=>Number(x.distancia_backbone_km??x.distancia_km??9999)-Number(y.distancia_backbone_km??y.distancia_km??9999));const e=sorted[0],dist=e.distancia_backbone_km??e.distancia_km??e.distancia_ao_backbone_km;n.innerHTML=`<b>Mais próxima do Backbone</b><br>${esc(e.municipio||e.regiao||e.id_evento||'Evento Fire')} • ${esc(e.classificacao||'FIRE')}${dist!=null?` • ${Number(dist).toFixed(1)} km`:''}`}
function setActiveViewTab(id){['tabMapa','tabComando','tabFire','tabRibeirao','tabRibeiraoGeral','tabSbc','tabFireHistory','tabMobile','tabTrajectory'].forEach(x=>document.getElementById(x)?.classList.toggle('active',x===id))}

function ribeiraoPointInPolygon(lon,lat,ring){let inside=false;for(let i=0,j=ring.length-1;i<ring.length;j=i++){const xi=Number(ring[i][0]),yi=Number(ring[i][1]),xj=Number(ring[j][0]),yj=Number(ring[j][1]);const hit=((yi>lat)!==(yj>lat))&&(lon<(xj-xi)*(lat-yi)/((yj-yi)||1e-12)+xi);if(hit)inside=!inside}return inside}
function ribeiraoOrient(a,b,c){return (b[0]-a[0])*(c[1]-a[1])-(b[1]-a[1])*(c[0]-a[0])}
function ribeiraoSegmentsCross(a,b,c,d){const o1=ribeiraoOrient(a,b,c),o2=ribeiraoOrient(a,b,d),o3=ribeiraoOrient(c,d,a),o4=ribeiraoOrient(c,d,b);return ((o1===0||o2===0||o1*o2<0)&&(o3===0||o4===0||o3*o4<0))}
function ribeiraoLineIntersects(coords,ring){if(!Array.isArray(coords)||coords.length<2||!ring?.length)return false;if(coords.some(p=>ribeiraoPointInPolygon(Number(p[0]),Number(p[1]),ring)))return true;for(let i=1;i<coords.length;i++){const a=coords[i-1],b=coords[i];for(let j=1;j<ring.length;j++){if(ribeiraoSegmentsCross(a,b,ring[j-1],ring[j]))return true}}return false}
function ribeiraoFeatureIntersects(f){const ring=ribeiraoPolygon?.geometry?.coordinates?.[0];if(!ring)return false;const g=f?.geometry||{},c=g.coordinates||[];if(g.type==='LineString')return ribeiraoLineIntersects(c,ring);if(g.type==='MultiLineString')return c.some(x=>ribeiraoLineIntersects(x,ring));return false}
function ribeiraoEventInside(e){const ring=ribeiraoPolygon?.geometry?.coordinates?.[0],lat=Number(e?.latitude),lon=Number(e?.longitude);return Boolean(ring&&Number.isFinite(lat)&&Number.isFinite(lon)&&ribeiraoPointInPolygon(lon,lat,ring))}
async function ensureRibeiraoGeometry(){if(ribeiraoPolygon)return true;const r=await fetch(`./municipios_sp_min.geojson?t=${Date.now()}`,{cache:'no-store'});if(!r.ok)throw new Error(`Malha municipal HTTP ${r.status}`);const d=await r.json();ribeiraoPolygon=(d.features||[]).find(f=>norm(f?.properties?.municipio)==='RIBEIRAO PRETO')||null;if(!ribeiraoPolygon)throw new Error('Limite municipal de Ribeirão Preto não encontrado');ribeiraoRoutes=(allFeatures||[]).filter(ribeiraoFeatureIntersects);return true}
function ribeiraoDrawBackbone(){if(layer){layer.remove();layer=null}if(!ribeiraoRoutes.length)return;layer=L.geoJSON({type:'FeatureCollection',features:ribeiraoRoutes},{style:f=>({color:colorFor(f.properties?.confianca),weight:4,opacity:.93}),onEachFeature:(f,l)=>{l.bindPopup(popupHtml(f.properties||{}));l.on('click',()=>document.getElementById('details').innerHTML=detailsHtml(f.properties||{}));l.on('mouseover',()=>l.setStyle({weight:7,opacity:1}));l.on('mouseout',()=>layer?.resetStyle(l))}}).addTo(map);if(ribeiraoBoundaryLayer)try{map.removeLayer(ribeiraoBoundaryLayer)}catch(e){};ribeiraoBoundaryLayer=L.geoJSON(ribeiraoPolygon,{style:{color:'#38bdf8',weight:2,opacity:.8,fillColor:'#38bdf8',fillOpacity:.025,dashArray:'7 7'},interactive:false}).addTo(map);try{map.fitBounds(ribeiraoBoundaryLayer.getBounds(),{padding:[22,22],maxZoom:11})}catch(e){}}
function ribeiraoRenderClimateStrip(){
 const strip=document.getElementById('climateStrip'),track=document.getElementById('climateStripTrack'),status=document.getElementById('climateStripStatus');if(!strip||!track||!status)return;
 const events=weatherEvents.filter(e=>(norm(e.municipio)==='RIBEIRAO PRETO'||norm(e.regiao)==='RIBEIRAO PRETO')&&climateIsRelevant(e));
 const dc=climateOfficialMunicipios(),max=events.reduce((m,e)=>Math.max(m,climateSeverityRank(e.nivel_risco)),1),sev=max>=4?'critico':max>=3?'alto':max>=2?'atencao':'monitoramento';
 strip.className=`climate-strip severity-${sev}`;status.textContent=events.length?`Ribeirão Preto • ${events.length} relevante${events.length===1?'':'s'}`:'Ribeirão Preto • monitoramento normal';
 if(!events.length){track.className='climate-strip-track climate-strip-static';track.innerHTML='<span class="climate-strip-empty">✅ Ribeirão Preto sem ameaças climáticas relevantes neste ciclo</span>';return}
 const items=events.map(e=>climateStripItemHtml(e,dc)).join('');track.className='climate-strip-track';track.innerHTML=`<div class="climate-strip-run">${items}${items}</div>`;
}
function ribeiraoHistoryAgeDays(e){return fireHistoryAgeHours(e)/24}
function ribeiraoRenderFire(){ribeiraoFireLayer.clearLayers();ribeiraoHistoryLayer.clearLayers();const active=fireEvents.filter(ribeiraoEventInside),hist=fireHistoryEvents.filter(ribeiraoEventInside);for(const e of active){const lat=Number(e.latitude),lon=Number(e.longitude),c=fireColor(e.classificacao);L.circleMarker([lat,lon],{radius:15,color:'#fff',weight:3,fillColor:c,fillOpacity:.96}).bindPopup(firePopupHtml(e)+`<div class="fire-popup-more">${fireDetailsHtml(e)}</div>`,{maxWidth:380}).bindTooltip(`🔥 Ribeirão • ${e.classificacao||'FIRE'}`).addTo(ribeiraoFireLayer)}for(const e of hist){const lat=Number(e.latitude),lon=Number(e.longitude),c=fireHistoryColor(e);L.circleMarker([lat,lon],{radius:8,color:c,weight:2,fillColor:c,fillOpacity:.25,opacity:.7,dashArray:'4 3'}).bindPopup(fireHistoryPopupHtml(e)).bindTooltip(`🔥 Histórico Ribeirão • ${e.quantidade_deteccoes||0} det.`).addTo(ribeiraoHistoryLayer)}ribeiraoRenderPanel(active,hist)}
function ribeiraoRenderPanel(active,hist){const set=(id,v)=>{const x=document.getElementById(id);if(x)x.textContent=v};set('ribeiraoRoutes',ribeiraoRoutes.length.toLocaleString('pt-BR'));set('ribeiraoActive',active.length.toLocaleString('pt-BR'));const h30=hist.filter(e=>{const d=ribeiraoHistoryAgeDays(e);return d>=0&&d<=30});set('ribeiraoHistory30',h30.length.toLocaleString('pt-BR'));set('ribeiraoHistoryTotal',hist.length.toLocaleString('pt-BR'));const near=document.getElementById('ribeiraoNearest');if(near){if(active.length){const x=[...active].sort((a,b)=>Number(a.distancia_backbone_km??a.distancia_km??9999)-Number(b.distancia_backbone_km??b.distancia_km??9999))[0],dist=x.distancia_backbone_km??x.distancia_km??x.distancia_ao_backbone_km;near.innerHTML=`<b>Mais próxima do Backbone de Ribeirão</b><br>${esc(x.id_evento||'Evento Fire')} • ${esc(x.classificacao||'FIRE')}${dist!=null?` • ${Number(dist).toFixed(1)} km`:''}`}else near.innerHTML='<b>Nenhuma queimada ativa em Ribeirão Preto neste ciclo.</b><br>Histórico e Backbone municipal permanecem visíveis.'}const list=document.getElementById('ribeiraoHistoryList');if(list){const latest=[...hist].sort((a,b)=>new Date(b.ultima_deteccao_utc||0)-new Date(a.ultima_deteccao_utc||0)).slice(0,12);list.innerHTML=latest.length?latest.map((e,i)=>`<button class="fire-history-row" data-rp-hist="${i}"><b>${esc(e.id_evento||'Fire histórico')}</b><span>${e.ultima_deteccao_utc?new Date(e.ultima_deteccao_utc).toLocaleString('pt-BR',{day:'2-digit',month:'2-digit',year:'2-digit',hour:'2-digit',minute:'2-digit'}):'—'} • ${esc(e.quantidade_deteccoes)} det. • ${esc(e.classificacao_proximidade||'—')}</span></button>`).join(''):'<small>Sem eventos históricos dentro do limite municipal.</small>';list.querySelectorAll('[data-rp-hist]').forEach(b=>b.onclick=()=>{const e=latest[Number(b.dataset.rpHist)],lat=Number(e?.latitude),lon=Number(e?.longitude);if(Number.isFinite(lat)&&Number.isFinite(lon))map.flyTo([lat,lon],12,{duration:.45})})}}
