function trajectoryCityCenter(name){const n=norm(name);const pools=[siteEvents,weatherEvents,defesaEvents,fireEvents];for(const pool of pools){const a=pool.filter(x=>norm(x.municipio||x.regiao)===n).map(x=>[Number(x.latitude),Number(x.longitude)]).filter(p=>Number.isFinite(p[0])&&Number.isFinite(p[1]));if(a.length)return[a.reduce((s,p)=>s+p[0],0)/a.length,a.reduce((s,p)=>s+p[1],0)/a.length]}return null}
