function trajectoryOfficial(){const seen=new Set(),out=[];for(const e of operationalDefesaEvents()){if(norm(e.status)!=='ATIVO_OFICIAL')continue;const k=`${e.id_alerta||e.tipo||e.titulo||''}|${norm(e.municipio)}`;if(seen.has(k))continue;seen.add(k);const age=importantOfficialAgeHours(e),sites=importantSitesFor(e.municipio),text=e.resumo||'',isPrev=norm(e.urgencia)==='PREVISTA',fresh=age==null||age<=24;const status=isPrev&&fresh?'PREVISÃO OFICIAL':'ALERTA OFICIAL ATIVO';let score=45+(norm(e.gravidade)==='EXTREME'?55:norm(e.gravidade)==='ALERTA'?20:0)+(sites.ate4h?10:0);out.push({kind:'oficial',score,urgent:true,municipio:e.municipio,lat:e.latitude,lon:e.longitude,time:importantTimeFromSummary(text),age,raios:importantNormText(text).includes('RAIOS'),mov:importantNormText(text).includes('DESLOCANDO-SE'),movementText:null,sites,text,gravidade:e.gravidade,tipo:e.tipo||e.titulo,fonte:e.fonte,urgencia:e.urgencia,status,sortTime:importantOfficialDate(e)?.getTime()||Date.now(),vigencia:e.vigencia});}return out}

function trajectoryRowsForCity(name){const n=norm(name),w=weatherEvents.find(e=>norm(e.municipio)===n),f=(forecastSpi.regioes||[]).find(e=>norm(e.regiao)===n);return Array.isArray(w?.previsao_horaria)&&w.previsao_horaria.length?w.previsao_horaria:(Array.isArray(f?.previsao_horaria)?f.previsao_horaria:[])}
function trajectoryRowRelevant(z){const gust=Number(z?.rajada_kmh||0),rain=Number(z?.precipitacao_mm||0),prob=Number(z?.probabilidade_chuva||0),storm=[95,96,99].includes(Number(z?.weather_code));return storm||rain>=.2||gust>=40||(prob>=70&&rain>0)}
function trajectoryWindowForCity(name){const now=Date.now(),rows=trajectoryRowsForCity(name).map(z=>({...z,_t:new Date(z.data_hora).getTime()})).filter(z=>Number.isFinite(z._t)&&z._t>=now-20*60000&&z._t<=now+12*3600000).sort((a,b)=>a._t-b._t);const rel=rows.filter(trajectoryRowRelevant);if(!rel.length)return null;const score=z=>Number(z.rajada_kmh||0)+Number(z.precipitacao_mm||0)*18+Number(z.probabilidade_chuva||0)*.25+([95,96,99].includes(Number(z.weather_code))?60:0),peak=[...rel].sort((a,b)=>score(b)-score(a))[0],fmt=t=>new Date(t).toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'});let end=rel[rel.length-1]._t+3600000;return{inicio:fmt(rel[0]._t),pico:fmt(peak._t),fim:fmt(end),fimTs:end,peak,rows:rel}}
function trajectorySelectedEvent(){const all=[...trajectoryObserved(),...trajectoryOfficial(),...trajectoryForecast()];return all.find(x=>trajectoryKey(x)===trajectorySelectedKey)||all[0]||null}
function trajectoryAiAnswer(mode){const el=document.getElementById('trajectoryAiAnswer');if(!el)return;const x=trajectorySelectedEvent(),groups=trajectoryForecastImpactSequence();if(!x){el.innerHTML='<b>Sem evento selecionado.</b>';return}const win=trajectoryWindowForCity(x.municipio),sites=x.sites||importantSitesFor(x.municipio);if(mode==='fim'){el.innerHTML=win?`<b>⏱️ ${esc(x.municipio)}</b><br>Janela relevante até aproximadamente <b>${esc(win.fim)}</b>. Pico previsto por volta de <b>${esc(win.pico)}</b>.`:`<b>⏱️ ${esc(x.municipio)}</b><br>Não há uma janela futura confiável neste ciclo.`;return}if(mode==='sites'){el.innerHTML=`<b>🔋 Exposição operacional</b><br>${esc(x.municipio)} possui <b>${sites.total??0}</b> site(s) no recorte e <b>${sites.ate4h??0}</b> com autonomia ≤4h.`;return}if(mode==='proximos'){const now=Date.now(),next=groups.filter(g=>g.t>=now).slice(0,4);el.innerHTML=next.length?`<b>➡️ Progressão prevista</b><br>${next.map(g=>`${new Date(g.t).toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'})}: ${g.items.slice(0,4).map(i=>esc(i.municipio)).join(', ')}`).join('<br>')}<br><small>Sequência da previsão regional; não é rastreamento confirmado da mesma célula.</small>`:'<b>➡️ Sem progressão futura relevante nas próximas horas.</b>';return}el.innerHTML=`<b>🛡️ Resumo preventivo — ${esc(x.municipio)}</b><br>Status: <b>${esc(x.status||'evento')}</b>${win?` • pico ${esc(win.pico)} • até ~${esc(win.fim)}`:''}<br>Sites ≤4h: <b>${sites.ate4h??0}</b>${x.gust>0?` • rajada prevista ${Number(x.gust).toFixed(0)} km/h`:''}${x.rain3h>0?` • chuva ${Number(x.rain3h).toFixed(1)} mm`:''}.`}
function trajectoryFutureCandidates(){const now=Date.now(),out=[];for(const r of weatherEvents){const lat=Number(r.latitude),lon=Number(r.longitude);if(!Number.isFinite(lat)||!Number.isFinite(lon))continue;const rows=(r.previsao_horaria||[]).filter(z=>{const t=new Date(z.data_hora).getTime();return Number.isFinite(t)&&t>=now-10*60000&&t<=now+12*3600000});if(!rows.length)continue;let best=null,bestScore=-1;for(const z of rows){const gust=Number(z.rajada_kmh||0),rain=Number(z.precipitacao_mm||0),prob=Number(z.probabilidade_chuva||0),storm=[95,96,99].includes(Number(z.weather_code)),score=gust+prob*.35+rain*18+(storm?60:0);if(score>bestScore){bestScore=score;best=z}}if(!best)continue;const gust=Number(best.rajada_kmh||0),rain=Number(best.precipitacao_mm||0),prob=Number(best.probabilidade_chuva||0),storm=[95,96,99].includes(Number(best.weather_code)),sites=importantSitesFor(r.municipio);const operationalThreat=storm||gust>=60||rain>=10;const activeRisk=Boolean(r.ameaca_ativa)&&['ALTO','CRITICO','CRÍTICO'].includes(String(r.nivel_risco||'').toUpperCase());if(!(operationalThreat||activeRisk))continue;out.push({kind:'previsao',score:bestScore,urgent:gust>=60||rain>=10||storm,municipio:r.municipio,lat,lon,time:new Date(best.data_hora).toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'}),iso:best.data_hora,gust,wind:Number(best.vento_kmh||0),dir:Number(best.direcao_vento_graus||0),rain3h:rain,prob3h:prob,storm,sites,fonte:'Weather Risk SPI',status:'PREVISÃO METEOROLÓGICA',sortTime:new Date(best.data_hora).getTime()})}return out.sort((a,b)=>b.score-a.score)}
function trajectoryNowItems(){return weatherEvents.filter(r=>r.ameaca_ativa&&['ALTO','CRITICO'].includes(norm(r.nivel_risco))&&Number.isFinite(Number(r.latitude))&&Number.isFinite(Number(r.longitude))).map(r=>({municipio:r.municipio,lat:Number(r.latitude),lon:Number(r.longitude),nivel:norm(r.nivel_risco),score:Number(r.score_risco||0),wind:Number(r.vento_atual_kmh||0),gust:Number(r.rajada_kmh||0),rain:Number(r.chuva_atual_mm||0),storm:Boolean(r.tempestade),sites:importantSitesFor(r.municipio)})).sort((a,b)=>(b.nivel==='CRITICO')-(a.nivel==='CRITICO')||b.rain-a.rain||b.gust-a.gust||b.score-a.score)}
function renderTrajectoryNow(){const el=document.getElementById('trajectoryNow');if(!el)return;const rows=trajectoryNowItems(),stamp=new Date().toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'});if(!rows.length){el.innerHTML=`<div class="trajectory-now-empty"><b>Sem ameaça ALTO/CRÍTICO ativa agora.</b><small>Última leitura da interface: ${esc(stamp)}.</small></div>`;return}el.innerHTML=`<div class="trajectory-now-head"><b>${rows.length} município(s) em ameaça ativa</b><span>leitura ${esc(stamp)}</span></div>`+rows.slice(0,6).map((x,i)=>`<button class="trajectory-now-row severity-${x.nivel==='CRITICO'?'severe':'high'}" data-now-i="${i}"><span class="trajectory-now-place"><b>${esc(x.municipio)}</b><small>${esc(x.nivel)}${x.storm?' • TEMPESTADE':''}</small></span><span class="trajectory-now-metrics"><i>🌧️ ${x.rain>0?`${x.rain.toFixed(1)} mm`:'sem chuva medida'}</i><i>💨 ${x.wind>0?`${x.wind.toFixed(0)} km/h`:'s/d'}</i><i>🌬️ ${x.gust>0?`${x.gust.toFixed(0)} km/h`:'s/d'}</i><i>🔋 ${x.sites.ate4h??0} ≤4h</i></span></button>`).join('')+`<small class="trajectory-now-note">Condição atual do Weather Risk SPI. Vento/chuva atuais são separados do pico futuro mostrado abaixo.</small>`;el.querySelectorAll('[data-now-i]').forEach(b=>b.onclick=()=>{const x=rows[Number(b.dataset.nowI)];trajectorySelectedKey=null;map.flyTo([x.lat,x.lon],9,{duration:.5});const ai=document.getElementById('trajectoryAiAnswer');if(ai)ai.innerHTML=`<b>🔴 AGORA • ${esc(x.municipio)}</b><br>Nível <b>${esc(x.nivel)}</b>. Chuva atual: <b>${x.rain>0?`${x.rain.toFixed(1)} mm`:'sem chuva medida'}</b> • vento atual: <b>${x.wind>0?`${x.wind.toFixed(0)} km/h`:'sem dado útil'}</b> • rajada: <b>${x.gust>0?`${x.gust.toFixed(0)} km/h`:'sem dado útil'}</b> • sites ≤4h: <b>${x.sites.ate4h??0}</b>. <small>O pico futuro pode ser mais intenso que a condição observada agora.</small>`})}
function trajectoryActiveThreats(){const now=Date.now(),out=[];for(const r of weatherEvents){const level=norm(r.nivel_risco),lat=Number(r.latitude),lon=Number(r.longitude);if(!r.ameaca_ativa||!['ALTO','CRITICO'].includes(level)||!Number.isFinite(lat)||!Number.isFinite(lon))continue;const gust=Number(r.rajada_kmh||0),rain=Number(r.chuva_atual_mm||0),total=Number(r.chuva_total_mm||0),prob=Number(r.probabilidade_chuva_pico||0),sites=importantSitesFor(r.municipio),ao=r.alerta_oficial||{},official=Boolean(ao.fonte),status=official?`ALERTA ${String(ao.fonte).toUpperCase()} • ${String(ao.severidade||level).toUpperCase()}`:`AMEAÇA ATIVA • ${level}`;out.push({kind:'previsao',score:Number(r.score_risco||0)+100+(official?80:0),urgent:level==='CRITICO'||['PERIGO','GRANDE PERIGO'].includes(String(ao.severidade||'').toUpperCase()),municipio:r.municipio,lat,lon,time:'AGORA',iso:new Date(now).toISOString(),gust,wind:Number(r.vento_atual_kmh||0),dir:Number(r.direcao_vento_graus||0),rain3h:rain,prob3h:prob,storm:Boolean(r.tempestade),sites,fonte:official?ao.fonte:(r.fonte_rajada||'Weather Risk'),status,sortTime:now,nivel_risco:level,chuva_total_mm:total,alerta_oficial:ao})}return out.sort((a,b)=>b.score-a.score)}
function trajectoryForecast(){const active=trajectoryActiveThreats(),future=trajectoryFutureCandidates();return [...active,...future].sort((a,b)=>b.score-a.score||a.sortTime-b.sortTime).slice(0,14)}
function renderTrajectoryFuture(){const el=document.getElementById('trajectoryFuture');if(!el)return;const arr=trajectoryFutureCandidates().slice(0,6);if(!arr.length){el.innerHTML='<span>Sem previsão horária disponível neste ciclo.</span>';return}el.innerHTML=arr.map(x=>`<button class="trajectory-future-row" data-future-city="${esc(x.municipio)}"><b>${esc(x.time)} • ${esc(x.municipio)}</b><span>🌬️ raj. ${Number(x.gust).toFixed(0)} km/h • 🌧️ ${Number(x.rain3h).toFixed(1)} mm • ${Number(x.prob3h).toFixed(0)}%${x.storm?' • ⚡ tempestade':''}${x.sites.ate4h?` • 🔋 ${x.sites.ate4h} ≤4h`:''}</span></button>`).join('');el.querySelectorAll('[data-future-city]').forEach(b=>b.onclick=()=>{const x=arr.find(z=>z.municipio===b.dataset.futureCity);if(x){trajectorySelectedKey=trajectoryKey(x);renderTrajectory();map.flyTo([x.lat,x.lon],9,{duration:.5})}})}
function trajectorySeverity(x){if(x.kind==='observado'){const n=norm(x.nivel_operacional);if(n==='CRITICO')return{key:'extreme',label:'OBSERVADO • CRÍTICO',color:'#dc2626'};if(n==='ALTO')return{key:'alerta',label:'OBSERVADO • ALTO',color:'#f97316'};return{key:'observed',label:'OBSERVADO • ATENÇÃO',color:'#eab308'}}if(x.kind!=='oficial')return{key:'forecast',label:'PREVISÃO METEOROLÓGICA',color:'#f59e0b'};const g=norm(x.gravidade);if(g==='EXTREME')return{key:'extreme',label:'DEFESA CIVIL • EXTREME',color:'#dc2626'};if(g==='ALERTA')return{key:'alerta',label:'DEFESA CIVIL • ALERTA',color:'#f97316'};return{key:'other',label:`DEFESA CIVIL • ${x.gravidade||'ALERTA'}`,color:'#eab308'}}
function trajectoryMarkerHtml(x){const sev=trajectorySeverity(x),status=x.status||'PREVISÃO',name=x.municipio||'Evento',serious=x.kind==='observado'||x.kind==='oficial'||x.storm||Number(x.gust||0)>=60||Number(x.rain3h||0)>=10,icon=x.kind==='observado'?'🌧️':(x.kind==='oficial'?'🚨':(x.storm?'⛈️':(Number(x.gust||0)>=60?'🌬️':'🌧️')));return L.divIcon({className:'trajectory-marker-wrap',html:`<div class="trajectory-event-marker severity-${sev.key} ${serious?'serious':''}" style="--traj-color:${sev.color}"><span class="trajectory-event-icon">${icon}</span><div><b>${esc(name)}</b><small>${esc(status)}</small></div></div>`,iconSize:[150,58],iconAnchor:[75,29]})}

function haversineKm(lat1,lon1,lat2,lon2){const R=6371,toR=x=>x*Math.PI/180,dLat=toR(lat2-lat1),dLon=toR(lon2-lon1),a=Math.sin(dLat/2)**2+Math.cos(toR(lat1))*Math.cos(toR(lat2))*Math.sin(dLon/2)**2;return 2*R*Math.atan2(Math.sqrt(a),Math.sqrt(1-a))}
function nearestMetar(lat,lon){lat=Number(lat);lon=Number(lon);if(!Number.isFinite(lat)||!Number.isFinite(lon))return null;const now=Date.now();let best=null;for(const o of metarObservations){const olat=Number(o.latitude),olon=Number(o.longitude),t=new Date(o.observado_em).getTime();if(!Number.isFinite(olat)||!Number.isFinite(olon)||!Number.isFinite(t))continue;const ageMin=(now-t)/60000;if(ageMin<0||ageMin>90)continue;const d=haversineKm(lat,lon,olat,olon);if(d>120)continue;if(!best||d<best.distancia_km)best={...o,distancia_km:d,idade_min:ageMin}}return best}
async function loadMetarObservations(){try{const r=await fetch(`${METAR_DATA}?t=${Date.now()}`,{cache:'no-store'});if(!r.ok)throw new Error(`METAR HTTP ${r.status}`);const o=await r.json();metarObservations=Array.isArray(o.estacoes)?o.estacoes:[];if(trajectoryMode)renderTrajectory()}catch(e){console.error('Falha observações METAR',e)}}
