function wlApplyReferenceViewport(){const v=document.getElementById('weatherLabView');if(!v)return;const mobile=window.innerWidth<=900;if(mobile){document.body.classList.add('weatherlab-reference-mobile');const base=1440,scale=Math.min(1,window.innerWidth/base);v.style.transform='scale('+scale+')';v.style.width=base+'px';const natural=Math.max(v.scrollHeight,820);v.style.marginBottom='-'+Math.max(0,natural*(1-scale))+'px';}else{document.body.classList.remove('weatherlab-reference-mobile');v.style.transform='';v.style.width='';v.style.marginBottom='';}setTimeout(()=>{if(weatherLabMap)weatherLabMap.invalidateSize()},60)}
