const FIRE_HISTORY_2025_DATA='data/fire-history-2025.json';
let fireHistory2025=null,fireHistoryMap2025=null,fireHistoryPointsLayer=null,fireHistoryBoundaryLayer=null;
const fhMonths=['Jan','Fev','Mar','Abr','Mai','Jun','Jul','Ago','Set','Out','Nov','Dez'];
async function loadFireHistory2025(){if(fireHistory2025)return fireHistory2025;const r=await fetch(`${FIRE_HISTORY_2025_DATA}?t=${Date.now()}`,{cache:'no-store'});if(!r.ok)throw new Error(`Fire histórico HTTP ${r.status}`);fireHistory2025=await r.json();return fireHistory2025}
function fhNum(v){return Number(v||0).toLocaleString('pt-BR')}
function fhRenderSide(d){document.getElementById('fhTotal').textContent=fhNum(d.total);document.getElementById('fhCities').textContent=fhNum(d.municipios);const vals=Object.entries(d.mensal||{}),peak=vals.sort((a,b)=>b[1]-a[1])[0]||['—',0];document.getElementById('fhPeak').textContent=`${fhMonths[Number(peak[0])-1]||peak[0]} • ${fhNum(peak[1])}`;const mx=Math.max(1,...Object.values(d.mensal||{}).map(Number));document.getElementById('fhMonthly').innerHTML=Object.entries(d.mensal||{}).map(([m,n])=>`<div class="fh-month-row"><span>${fhMonths[Number(m)-1]}</span><i><b style="width:${Math.max(2,Number(n)/mx*100)}%"></b></i><strong>${fhNum(n)}</strong></div>`).join('');const dmax=Math.max(1,...Object.values(d.ddds||{}).map(Number));document.getElementById('fhDdds').innerHTML=Object.entries(d.ddds||{}).map(([ddd,n])=>`<button type="button" data-fh-ddd="${esc(ddd)}"><span>DDD ${esc(ddd)}</span><i><b style="width:${Number(n)/dmax*100}%"></b></i><strong>${fhNum(n)}</strong></button>`).join('');document.getElementById('fhTopCities').innerHTML=(d.top_municipios||[]).slice(0,12).map((x,i)=>`<div><span>${i+1}. ${esc(x.municipio)}</span><b>${fhNum(x.total)}</b></div>`).join('');const ann=d.historico_anual||{},amx=Math.max(1,...Object.values(ann).map(Number));document.getElementById('fhAnnual').innerHTML=Object.entries(ann).map(([y,n])=>`<div class="fh-year ${y==='2025'?'current':''}"><span>${y}</span><i><b style="width:${Number(n)/amx*100}%"></b></i><strong>${fhNum(n)}</strong></div>`).join('');document.querySelectorAll('[data-fh-ddd]').forEach(b=>b.onclick=()=>{const sel=document.getElementById('fireHistoryDddFilter');sel.value=b.dataset.fhDdd;fhRenderMap(b.dataset.fhDdd,true)})}
function fhEnsureMap(){if(fireHistoryMap2025)return;fireHistoryMap2025=L.map('fireHistoryMap',{preferCanvas:true,zoomControl:true,minZoom:5});L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:18,attribution:'© OpenStreetMap'}).addTo(fireHistoryMap2025);fireHistoryPointsLayer=L.layerGroup().addTo(fireHistoryMap2025);fireHistoryMap2025.setView([-22.3,-48.7],7)}
function fhIcon(){return L.divIcon({className:'fh-fire-icon',html:'🔥',iconSize:[18,18],iconAnchor:[9,9]})}
function fhRenderMap(filter='ALL',fit=false){if(!fireHistory2025)return;fhEnsureMap();fireHistoryPointsLayer.clearLayers();const pts=(fireHistory2025.pontos||[]).filter(p=>filter==='ALL'||String(p.ddd)===String(filter)),bounds=[];const icon=fhIcon();for(const p of pts){const lat=Number(p.lat),lon=Number(p.lon);if(!Number.isFinite(lat)||!Number.isFinite(lon))continue;L.marker([lat,lon],{icon,keyboard:false}).bindTooltip(`<b>🔥 ${esc(p.municipio)}</b><br>DDD ${esc(p.ddd)} • ${esc((p.data||'').replace(' ',' • '))}<br>${esc(p.bioma||'')}`,{direction:'top'}).addTo(fireHistoryPointsLayer);bounds.push([lat,lon])}document.getElementById('fhVisible').textContent=`${fhNum(pts.length)} focos visíveis${filter==='ALL'?'':` • DDD ${filter}`}`;if((fit||!fireHistoryMap2025._fhFitted)&&bounds.length){fireHistoryMap2025.fitBounds(bounds,{padding:[18,18],maxZoom:9});fireHistoryMap2025._fhFitted=true}setTimeout(()=>fireHistoryMap2025.invalidateSize(),60)}
async function showFireHistoryTab(){try{leaveRibeiraoGeral();leaveRibeiraoMode();leaveTrajectoryMode();leaveMobileMode();leaveFireMode();if(typeof leaveWeatherLab==='function')leaveWeatherLab();if(typeof leaveTacticalMode==='function')leaveTacticalMode()}catch(e){};for(const id of ['mapView','commandView','ribeiraoGeralView','weatherLabView','tacticalView']){const x=document.getElementById(id);if(x)x.hidden=true}const v=document.getElementById('fireHistoryView');if(v)v.hidden=false;setActiveViewTab('tabFireHistory');try{const d=await loadFireHistory2025();fhRenderSide(d);fhRenderMap(document.getElementById('fireHistoryDddFilter')?.value||'ALL',true)}catch(e){console.error(e);document.getElementById('fhVisible').textContent='Falha ao carregar histórico INPE'}}
