// Captura automatizada do boletim DEV: ativa somente com ?capture=command.\n// São Bernardo do Campo • visão municipal DEV
async function sbcFetchForecast(){
 const u='https://api.open-meteo.com/v1/forecast?latitude=-23.6914&longitude=-46.5646&current=wind_speed_10m,wind_gusts_10m,precipitation&hourly=precipitation,wind_speed_10m,wind_gusts_10m&forecast_days=3&timezone=America%2FSao_Paulo';
 const r=await fetch(u,{cache:'no-store'}); if(!r.ok) throw new Error('Open-Meteo '+r.status); return r.json();
}
function sbcCemadenRows(){return (Array.isArray(cemadenObservations)?cemadenObservations:[]).filter(o=>norm(o?.municipio||'')==='SAO BERNARDO DO CAMPO')}
function sbcFmt(v,d=1){v=Number(v);return Number.isFinite(v)?v.toFixed(d):'—'}
async function renderSbcView(){
 const root=document.getElementById('sbcView'); if(!root)return;
 const rows=sbcCemadenRows();
 const n=v=>Number(v);
 const r1=Math.max(0,...rows.map(x=>n(x.chuva_1h_mm??x.chuva1h??0)).filter(Number.isFinite));
 const r24=Math.max(0,...rows.map(x=>n(x.chuva_24h_mm??x.chuva24h??0)).filter(Number.isFinite));
 document.getElementById('sbcRain1').textContent=sbcFmt(r1)+' mm';
 document.getElementById('sbcRain24').textContent=sbcFmt(r24)+' mm';
 document.getElementById('sbcStations').textContent=rows.length;
 const list=[...rows].sort((x,y)=>n(y.chuva_24h_mm??0)-n(x.chuva_24h_mm??0));
 document.getElementById('sbcNow').innerHTML=list.length?`<div class="sbc-now-main"><strong>${sbcFmt(r1)} mm/1h</strong><span>maior leitura municipal agora</span><b>${sbcFmt(r24)} mm/24h</b></div>`:'<div class="sbc-empty">Sem leitura CEMADEN municipal neste ciclo.</div>';
 document.getElementById('sbcStationsList').innerHTML=list.map(x=>`<div class="sbc-station"><b>${esc(x.estacao||x.codigo||'Estação')}</b><span>1h <strong>${sbcFmt(x.chuva_1h_mm)} mm</strong></span><span>3h <strong>${sbcFmt(x.chuva_3h_mm)} mm</strong></span><span>24h <strong>${sbcFmt(x.chuva_24h_mm)} mm</strong></span><small>${esc(x.observado_em||'')}</small></div>`).join('')||'<div class="sbc-empty">Sem estações disponíveis.</div>';
 try{
  const f=await sbcFetchForecast(),cur=f.current||{},h=f.hourly||{},times=h.time||[],now=Date.now(),idx=times.map((t,i)=>[Date.parse(t),i]).filter(x=>x[0]>=now&&x[0]<=now+48*3600e3).map(x=>x[1]);
  const rain=idx.reduce((s,i)=>s+n(h.precipitation?.[i]||0),0), gust=Math.max(0,...idx.map(i=>n(h.wind_gusts_10m?.[i]||0))), wind=n(cur.wind_speed_10m||0);
  document.getElementById('sbcWind').textContent=sbcFmt(wind)+' km/h'; document.getElementById('sbcGust').textContent=sbcFmt(gust)+' km/h'; document.getElementById('sbcRain48').textContent=sbcFmt(rain)+' mm';
  const blocks=[]; for(let k=0;k<idx.length;k+=6){const ids=idx.slice(k,k+6),i0=ids[0]; if(i0==null)continue; blocks.push(`<div class="sbc-fc"><b>${new Date(times[i0]).toLocaleString('pt-BR',{weekday:'short',hour:'2-digit',minute:'2-digit'})}</b><span>🌧 ${sbcFmt(ids.reduce((s,i)=>s+n(h.precipitation?.[i]||0),0))} mm</span><span>🌬 ${sbcFmt(Math.max(0,...ids.map(i=>n(h.wind_gusts_10m?.[i]||0))))} km/h</span></div>`)}
  document.getElementById('sbcForecast').innerHTML=`<div class="sbc-fc-summary"><span><small>Agora</small><b>${sbcFmt(cur.precipitation||0)} mm</b></span><span><small>Vento</small><b>${sbcFmt(wind)} km/h</b></span><span><small>Rajada agora</small><b>${sbcFmt(cur.wind_gusts_10m||0)} km/h</b></span></div><div class="sbc-fc-grid">${blocks.join('')}</div>`;
  let level='BAIXO',msg='Condição municipal sem sinal meteorológico severo pelos dados disponíveis.'; if(gust>=70||rain>=50){level='ALTO';msg='Janela de atenção elevada: priorizar vento/rajadas e acumulado de chuva nas próximas 48h.'} else if(gust>=50||rain>=25||r24>=20){level='ATENÇÃO';msg='Há sinal de atenção municipal. Acompanhar evolução de rajadas, chuva acumulada e alertas oficiais.'}
  document.getElementById('sbcStatus').textContent=level; document.getElementById('sbcAiText').innerHTML=`<b>${level}</b> • ${msg} <span>Observado: até ${sbcFmt(r1)} mm/1h e ${sbcFmt(r24)} mm/24h • Previsão 48h: ${sbcFmt(rain)} mm, rajada até ${sbcFmt(gust)} km/h.</span>`;
 }catch(e){console.error('SBC forecast',e);document.getElementById('sbcForecast').innerHTML='<div class="sbc-empty">Previsão indisponível neste ciclo.</div>';document.getElementById('sbcAiText').textContent='CEMADEN disponível; previsão meteorológica temporariamente indisponível.'}
 document.getElementById('sbcUpdated').textContent='Atualizado '+new Date().toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'})+' • Brasília';
}
